package com.arqly.backend.entity;import jakarta.persistence.*;import java.math.*;import java.time.*;
@Entity @Table(name="financial_installments") public class FinancialInstallment extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="financial_entry_id",nullable=false)private FinancialEntry entry;@Column(nullable=false)private int installmentNumber;private String description;@Column(nullable=false,precision=15,scale=2)private BigDecimal amount;@Column(nullable=false)private LocalDate dueDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialInstallmentStatus status=FinancialInstallmentStatus.OPEN;@Column(nullable=false,precision=15,scale=2)private BigDecimal settledAmount=BigDecimal.ZERO;public FinancialEntry getEntry(){return entry;}public void setEntry(FinancialEntry v){entry=v;}public int getInstallmentNumber(){return installmentNumber;}public void setInstallmentNumber(int v){installmentNumber=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public LocalDate getDueDate(){return dueDate;}public void setDueDate(LocalDate v){dueDate=v;}public FinancialInstallmentStatus getStatus(){return status;}public void setStatus(FinancialInstallmentStatus v){status=v;}public BigDecimal getSettledAmount(){return settledAmount;}public void setSettledAmount(BigDecimal v){settledAmount=v;}}
